// @ts-check
import { defineConfig } from 'astro/config';
import react from '@astrojs/react';
import tailwindcss from '@tailwindcss/vite';
import sitemap from '@astrojs/sitemap';
import { readFileSync } from 'node:fs';

/**
 * Product routes that must stay out of the sitemap.
 *
 * Generated by scripts/gen-products.mjs from data/products/families.csv.
 * Read as JSON because this config is plain JS and cannot import the
 * TypeScript data layer. If the file is missing the filter is a no-op —
 * the build then fails earlier at the gen:products gate, not here.
 */
const PRODUCT_ROUTES = (() => {
	try {
		return JSON.parse(readFileSync(new URL('./src/data/products/routes.json', import.meta.url), 'utf8'));
	} catch {
		return { draft: [], published: [] };
	}
})();
/** @type {string[]} */
const DRAFT_PRODUCT_ROUTES = PRODUCT_ROUTES.draft ?? [];
/** @type {string[]} */
const DRAFT_CATEGORY_ROUTES = PRODUCT_ROUTES.draftCategories ?? [];
/** @type {string[]} */
const DRAFT_OVERVIEW_ROUTES = PRODUCT_ROUTES.draftOverview ?? [];

// ─────────────────────────────────────────────────────────────────────────────
// NOTE ON `root` / WINDOWS PATH CASING  (do NOT set `root` here)
// ─────────────────────────────────────────────────────────────────────────────
// Astro derives every page's module URL from `config.root`
//   (`static-build.js`: `new URL("./" + pageData.component, settings.config.root)`)
// and keys its page registry by `viteID(componentURL)` = `fileURLToPath()`.
//
// `config.root` defaults to `process.cwd()` — the path string exactly as the
// caller typed it. Vite/Rollup, in contrast, resolve module ids to the REAL
// on-disk path (canonical drive-letter casing). On Windows, launching the build
// from a lower-cased path (e.g. `c:\Users\...`) therefore produced registry keys
// like `c:/Users/...` while Vite used `C:/Users/...`. The CSS→page lookup
// silently failed, `pagesToCss` stayed empty, every CSS asset was treated as
// "orphaned" and DELETED — and the whole site shipped with ZERO CSS while the
// build reported success.
//
// Setting `root` explicitly does NOT fix it: Astro's config schema transforms
// it with `new URL(...)` / `resolveDirAsUrl(...)`, and URL parsing lower-cases
// the drive letter (it is parsed as a URL *scheme*).
//
// The correct fix lives in the build launcher (`scripts/astro-build.mjs`),
// which spawns Astro with a canonicalised working directory so that Astro and
// Vite always agree on path casing, no matter how the build was invoked.
//
// This project inherits that launcher verbatim. Do not "simplify" the build
// script back to a bare `astro build`.
//
// https://astro.build
export default defineConfig({
  // Deployment target. NOTE: the domain identifies the site for SEO/deploy
  // purposes ONLY. The site's visual language comes exclusively from the
  // reference site (see docs/reference-spec.md §A.0) — it does NOT inherit
  // the design system of the sibling project at cnc.bozemetal.com.
  site: 'https://fastener.bozemetal.com',
  output: 'static',
  trailingSlash: 'always',
  build: {
    // Inline all Astro-collected CSS into HTML. The stylesheet is
    // render-blocking; inlining removes the extra round-trip at the cost of a
    // larger HTML document. Public/ cache headers should mark the HTML as
    // revalidated rather than immutable.
    inlineStylesheets: 'always',
  },
  integrations: [
    react(),
    sitemap({
      // Diagnostic pages must not be indexed.
      filter: (page) =>
        !page.includes('/thank-you') &&
        !page.includes('/image-catalog') &&
        !page.includes('/token-probe') &&
        !page.includes('/logo-probe') &&
        !page.includes('/design-system') &&
        // Product families with status=draft must not enter the sitemap.
        // The published set is generated from data/products/families.csv by
        // scripts/gen-products.mjs and written to src/data/products/.
        !DRAFT_PRODUCT_ROUTES.some((p) => page.includes(p)) &&
        // Category pages whose families are all draft must not enter either —
        // the page itself emits noindex, so sitemap and robots must agree.
        !DRAFT_CATEGORY_ROUTES.some((p) => page.includes(p)) &&
        // The product overview page emits noindex when no family is published —
        // sitemap and robots must agree, so it leaves the sitemap too.
        !DRAFT_OVERVIEW_ROUTES.some((p) => page.includes(p)),
      changefreq: 'weekly',
      priority: 0.7,
      lastmod: new Date(),
    }),
  ],
  vite: {
    plugins: [tailwindcss()],
  },
});
